// @vitest-environment node
/**
 * csi-mf-parse.test.ts — CSI tagger v2, S1 (parser half): the MasterFormat PDF parser.
 *
 * Fixture-driven (public MasterFormat text, `fixtures/csi-v2/mf-pages-excerpt.json`,
 * regenerated by `eval/csi/mf-fixture-extract.ts`), so it runs without the PDF. The
 * full-PDF census at the bottom runs only where the PDF exists.
 *
 * Goldens (PLAN §5.1), each read off the fixture's item coordinates before asserting:
 *   p.642  "03 00 00 concrete" text x 454.94; "03 01 00 cleaning, maintenance" x 465.78
 *          (deeper by 10.8 pt) → phrase "cleaning, maintenance, concrete". A CODED head.
 *   p.653  "11 21 73 dry cleaning" sits at sub level at the TOP of column 1; "epoxy mortar"
 *          and "11 00 00 equipment" are heads in column 0.
 *   p.665  "23 00 00 HVAC" (coded head) → "23 40 00 air cleaning devices, HVAC".
 */
import { describe, it, expect } from "vitest";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import {
  DEFAULT_PDF,
  TITLE_STRIP_RE,
  buildLines,
  countSplitWordArtifacts,
  dedupeAdjacentWords,
  extractPages,
  levelOf,
  parseDocument,
  parseIndex,
  parseMasterList,
  stripTitle,
  type PdfItem,
  type PdfPage,
} from "../../../eval/csi/mf-parse";

const FIXTURE = join(process.cwd(), "src/lib/__tests__/fixtures/csi-v2/mf-pages-excerpt.json");
const fixture = JSON.parse(readFileSync(FIXTURE, "utf-8")) as { pdfSha256: string; pages: PdfPage[] };
const page = (n: number): PdfPage => {
  const p = fixture.pages.find((x) => x.page === n);
  if (!p) throw new Error(`fixture lacks page ${n}`);
  return p;
};
const masterLines = (...ns: number[]) => ns.flatMap((n) => buildLines(page(n), { splitGaps: true }));
const indexLines = (...ns: number[]) => ns.flatMap((n) => buildLines(page(n)));

/** A synthetic one-column master page: [code, title] rows at the measured x positions. */
function syntheticPage(rows: [string, string][]): PdfPage {
  const items: PdfItem[] = [];
  rows.forEach(([code, title], k) => {
    const y = 700 - k * 12.6;
    items.push({ str: code, x: 55.4, y, h: 11, w: 42.8 });
    items.push({ str: " ", x: 98.2, y, h: 0, w: 4.3 });
    items.push({ str: title, x: 145.4, y, h: 11, w: 150 });
  });
  return { page: 1, width: 612, height: 792, items };
}

describe("csi-mf-parse — keyword index head rule (PLAN §5.1 goldens)", () => {
  it("p.642: a CODED head owns the deeper rows under it — cleaning, maintenance, concrete → 03 01 00", () => {
    const { index } = parseIndex(indexLines(642));
    const e = index.find((x) => x.code === "03 01 00" && x.text === "cleaning, maintenance");
    expect(e).toMatchObject({ head: "concrete", phrase: "cleaning, maintenance, concrete", page: 642 });
    // The head itself is an entry with no head.
    expect(index.find((x) => x.code === "03 00 00" && x.text === "concrete")?.head).toBeNull();
  });

  it("p.653: dry cleaning (11 21 73) never takes the head 'epoxy mortar'", () => {
    const reset = parseIndex(indexLines(653), { carryHeads: false });
    const carry = parseIndex(indexLines(653));
    // 'epoxy mortar' IS a head on this page — the rule must find it and not leak it.
    expect(reset.index.some((x) => x.head === "epoxy mortar" && x.text === "for masonry")).toBe(true);
    for (const r of [reset, carry]) {
      expect(r.index.filter((x) => x.code === "11 21 73" && x.head === "epoxy mortar")).toEqual([]);
    }
    // PLAN as written: head resets at the column break, so the row is head-less and dropped.
    expect(reset.index.some((x) => x.code === "11 21 73" && x.text === "dry cleaning")).toBe(false);
    expect(reset.headless).toBeGreaterThan(0);
    // carryHeads: the open head at the bottom of column 0 is "11 00 00 equipment".
    expect(carry.index.find((x) => x.code === "11 21 73" && x.text === "dry cleaning")?.phrase).toBe(
      "dry cleaning, equipment",
    );
  });

  it("p.665: air cleaning devices under the coded head 23 00 00 HVAC", () => {
    const { index } = parseIndex(indexLines(665));
    expect(index.find((x) => x.code === "23 40 00")).toMatchObject({
      text: "air cleaning devices",
      head: "HVAC",
      phrase: "air cleaning devices, HVAC",
    });
  });

  it("p.653: a wrapped coded head stays one head (equal employment / opportunity → affidavit)", () => {
    const { index } = parseIndex(indexLines(653));
    expect(index.find((x) => x.code === "00 45 36")?.phrase).toBe("affidavit, equal employment opportunity");
  });

  it("p.640: a same-x run after a coded entry splits into its wrapped tail + a new head", () => {
    const { index } = parseIndex(indexLines(640));
    expect(index.find((x) => x.code === "33 82 53")).toMatchObject({
      text: "cleaning, lubrication chemicals, communications",
      head: null,
    });
    expect(index.find((x) => x.code === "03 01 00")?.phrase).toBe("rehabilitation, cleaning concrete");
  });

  it("p.629: a plain line under a coded entry that is not its wrap starts a new head", () => {
    const { index } = parseIndex(indexLines(629));
    expect(index.find((x) => x.code === "09 91 00")).toMatchObject({ text: "acrylic latex paint", head: null });
    expect(index.find((x) => x.code === "06 60 00")?.phrase).toBe("fabrications, acrylic plastic");
  });

  it("p.642: abbreviation rows and '… X - see Y' synonym rows are captured, not indexed", () => {
    const r = parseIndex(indexLines(642));
    expect(r.abbrevRows).toContainEqual({ abbr: "CATV", expansion: "community antenna television" });
    expect(r.synonyms).toContainEqual({ from: "computer flooring", to: "access flooring" });
    expect(r.index.some((x) => x.text.includes(" - see"))).toBe(false);
  });
});

describe("csi-mf-parse — master list (PLAN §5.1/§5.2 parse half)", () => {
  it("over-grab: the strip cuts a division side note off the Level-2 row it attached to", () => {
    // p.46's "May be used as Division level Section" sits above the first code, so it
    // trails the last open entry — p.40's range row "48 80 00 to 48 90 00 Unassigned".
    const mp = parseMasterList(masterLines(40, 46));
    expect(mp.master.find((e) => e.code === "48 80 00")?.title).toBe("Unassigned");
    expect(mp.overGrabTitles).toBe(1);
    expect(mp.master.filter((e) => TITLE_STRIP_RE.test(e.title))).toEqual([]);
  });

  it("stripTitle: cuts at the first strip match", () => {
    expect(stripTitle("Closeout Submittals Level 2 Numbers and Titles")).toMatchObject({
      title: "Closeout Submittals",
      overGrab: true,
    });
    expect(stripTitle("General Requirements May be used as Division level").title).toBe("General Requirements");
    expect(stripTitle("Door Hardware").overGrab).toBe(false);
    // 43 05 05 prints a trailing period on the real PDF; titles never end in one.
    expect(stripTitle("Selective Demolition for Process Gas and Liquid Handling, Purification, and Storage Equipment.").title)
      .toBe("Selective Demolition for Process Gas and Liquid Handling, Purification, and Storage Equipment");
  });

  it("titles starting for|see are rejected into rejectedTitles (S2 substitutes the TSV title)", () => {
    expect(stripTitle("for metal frames only.")).toMatchObject({ title: "", rejected: true });
    const mp = parseMasterList(buildLines(syntheticPage([["07 99 01", "For Testing Only"], ["07 99 02", "Real Title"]])));
    expect(mp.rejectedTitles).toEqual([{ code: "07 99 01", title: "For Testing Only" }]);
    expect(mp.master.find((e) => e.code === "07 99 01")?.title).toBe("");
  });

  it("p.179: 'for …' See rows are references of the entry, never entries", () => {
    const mp = parseMasterList(masterLines(179));
    const e = mp.master.find((x) => x.code === "08 11 00");
    expect(e?.see.map((s) => s.code)).toEqual(["08 12 00", "08 13 00", "08 32 13", "08 41 00", "08 71 00"]);
    expect(e?.see[0]).toEqual({ code: "08 12 00", text: "for metal frames only." });
    expect(mp.master.some((x) => x.code === "08 13 00")).toBe(false);
    expect(mp.master.filter((x) => /^(for|see)\b/i.test(x.title))).toEqual([]);
  });

  it("p.179: Includes / Alternate Terms blocks and levels", () => {
    const mp = parseMasterList(masterLines(179));
    const e = mp.master.find((x) => x.code === "08 11 00");
    expect(e).toMatchObject({ title: "Metal Doors and Frames", level: 3 });
    expect(e?.includes[0]).toMatch(/^hinged or pivoting doors, .* and other openings\.$/);
    expect(e?.altTerms).toEqual(["Muntz metal", "hollow metal doors and frames", "steel doors and frames", "yellow metal"]);
    expect(mp.master.find((x) => x.code === "08 11 13.13")).toMatchObject({
      title: "Standard Hollow Metal Doors and Frames",
      level: 5,
    });
  });

  it("p.560: a division title wraps by font size and is split from the explanation column", () => {
    const mp = parseMasterList(masterLines(560));
    expect(mp.master.find((x) => x.code === "43 00 00")?.title).toBe(
      "Process Gas and Liquid Handling, Purification, and Storage Equipment",
    );
  });

  it("adjacent duplicate words are removed and counted", () => {
    expect(dedupeAdjacentWords("Metal Metal Doors and and Frames")).toEqual({ text: "Metal Doors and Frames", removed: 2 });
    expect(stripTitle("Door Door Hardware")).toMatchObject({ title: "Door Hardware", dupWords: 1 });
  });

  it("levelOf by digit shape", () => {
    expect([levelOf("08 00 00"), levelOf("08 10 00"), levelOf("08 11 13"), levelOf("08 11 13.13")]).toEqual([2, 3, 4, 5]);
  });

  it("split-word artifacts are counted (pypdf printed 'Scree n'; pdfjs prints none)", () => {
    expect(countSplitWordArtifacts(["Fire Scree n Doors", "Screen Walls", "Screen Doors", "Bidder's Qualifications"])).toBe(1);
    expect(countSplitWordArtifacts(["Hand-Held Emergency Drench Hoses", "Hand Tools", "Held Items"])).toBe(0);
  });
});

describe("csi-mf-parse — document report counters (fixture)", () => {
  const doc = parseDocument(fixture.pages);
  it("dangling See codes and dangling index codes are counted against the parsed codes", () => {
    const codes = new Set(doc.master.map((e) => e.code));
    const dangling = doc.master.flatMap((e) => e.see).filter((s) => s.code !== "?" && !codes.has(s.code));
    expect(doc.report.danglingSee).toBe(dangling.length);
    expect(doc.report.danglingSee).toBeGreaterThan(0);
    expect(doc.report.danglingIndexCodes).toBe(doc.index.filter((e) => !codes.has(e.code)).length);
  });
  it("Unassigned rows (incl. range rows) are counted; split words and dup words are 0", () => {
    expect(doc.master.filter((e) => e.title === "Unassigned").map((e) => e.code)).toEqual(
      expect.arrayContaining(["48 40 00", "48 80 00"]),
    );
    expect(doc.report.unassigned).toBe(doc.master.filter((e) => e.title === "Unassigned").length);
    expect(doc.report.splitWordArtifacts).toBe(0);
    expect(doc.report.dupWords).toBe(0);
  });
});

/**
 * Full-PDF census (PLAN §3 / IMPLEMENTATION §II S1). Runs only where the PDF exists.
 * MEASURED 2026-10-19: 8,985 codes = 35/1,458/5,009/2,483. The plan's 8,986 (…/5,010/…)
 * counted one Notes sentence as an entry: "44 13 80 through 44 13 89 includes equipment
 * that collects …" — 44 13 80 is not a MasterFormat code (absent from the TSV too).
 */
describe.skipIf(!existsSync(DEFAULT_PDF))("csi-mf-parse — full-PDF census", () => {
  it("codes, levels, index, report counters, title fidelity", async () => {
    const pages = await extractPages(DEFAULT_PDF);
    // PLAN §5.1 literal (reset at every column/page break) — kept pinned for comparison.
    const doc = parseDocument(pages, { carryHeads: false });
    const levels = [2, 3, 4, 5].map((lv) => doc.master.filter((e) => e.level === lv).length);
    expect(doc.pages).toBe(714);
    expect(doc.master.length).toBe(8985);
    expect(levels).toEqual([35, 1458, 5009, 2483]);
    expect(doc.extra.masterPages).toEqual([18, 625]);
    expect(doc.extra.indexPages).toEqual([628, 713]);
    // PLAN §5.1 as written (head reset at every column/page break):
    expect(doc.index.length).toBe(11203);
    expect(doc.report.headless).toBe(1312);
    expect(doc.abbrevRows.length).toBe(83);
    expect(doc.synonyms.length).toBe(253);
    const { rejectedTitles, ...counters } = doc.report;
    expect(rejectedTitles).toEqual([]);
    expect(counters).toEqual({
      overGrabTitles: 1,
      dupWords: 0,
      headless: 1312,
      danglingIndexCodes: 114,
      danglingSee: 5,
      splitWordArtifacts: 0,
      unassigned: 51,
    });
    expect(doc.master.filter((e) => TITLE_STRIP_RE.test(e.title)).length).toBe(0);
    // DEFAULT (carryHeads): every coded index row survives (12,511 = PLAN §3's pdfjs count).
    const carry = parseDocument(pages);
    expect(carry.index.length).toBe(12511);
    expect(carry.report.headless).toBe(4);
    expect(carry.report.danglingIndexCodes).toBe(126);
    // Title fidelity vs the TSV (normalized: lowercase, alphanumerics only).
    const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, "");
    const tsv = new Map<string, string>();
    for (const row of readFileSync(join(process.cwd(), "src/data/csi-masterformat.tsv"), "utf-8").split("\n").slice(1)) {
      const c = row.split("\t");
      if (c.length < 4) continue;
      const raw = c[2].trim();
      tsv.set(`${raw.slice(0, 2)} ${raw.slice(2, 4)} ${raw.slice(4)}`, c[3]);
    }
    const both = doc.master.filter((e) => tsv.has(e.code));
    const exact = both.filter((e) => norm(e.title) === norm(tsv.get(e.code) as string)).length;
    expect(exact / both.length).toBeGreaterThanOrEqual(0.968);
  }, 180_000);
});
